public void generateGraph(Graph<V,E> target,Map<String,V> resultMap){
    // Get the number of vertices in the graph
    int n = target.getVertexCount();

    // Map to keep track of whether a vertex has already been processed
    Map<V,Boolean> processedMap = new HashMap<>();

    // Initialize the map with all vertices set to false
    for (V v : target.getVertices()) {
        processedMap.put(v, false);
    }

    // Loop through all vertices
    for (V v : target.getVertices()) {
        // If the vertex has already been processed, continue to next vertex
        if (processedMap.get(v)) {
            continue;
        }
        // Otherwise, find all vertices that are connected to v and form a complete bipartite graph with v
        List<V> connectedVertices = new ArrayList<>();
        for (E e : target.getEdges(v)) {
            V u = e.getOpposite(v);
            connectedVertices.add(u);
        }
        // Add the current vertex to the result map
        resultMap.put(v, target.get(v));
        // Add all connected vertices to the result map
        for (V u : connectedVertices) {
            resultMap.put(u, target.get(u));
        }
        // Set the current vertex and all connected vertices as processed
        processedMap.put(v, true);
        for (V u : connectedVertices) {
            processedMap.put(u, true);
        }
    }
}
