/**
 * Unescapes any Java literals found in the input.
 * 
 * For example, it will turn a sequence of '\' and 'n' into a newline character, unless the '\' is preceded by another '\'.
 * 
 * @param str the input string to unescape
 * @return a new unescaped string
 * @throws Exception if an invalid escape sequence is encountered
 */
public static String unescapeJava(String str) {
    char[] arr = str.toCharArray();
    StringBuilder builder = new StringBuilder();
    for (int i = 0; i < arr.length; i++) {
        char c = arr[i];
        if (c == '\\' && i + 1 < arr.length) {
            char d = arr[i + 1];
            switch (d) {
                case 'n':
                    builder.append('\n');
                    break;
                case 'r':
                    builder.append('\r');
                    break;
                case 't':
                    builder.append('\t');
                    break;
                case '\\':
                    builder.append('\\');
                    break;
                default:
                    throw new Exception("Invalid escape sequence: \\" + d);
            }
            i++;
        } else {
            builder.append(c);
        }
    }
    return builder.toString();
}

