public List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

  // Create an instance of a ThreadSnapshotParser
  ThreadSnapshotParser parser = new ThreadSnapshotParser(file);

  // Loop through the time ranges and parse the corresponding snapshots
  for (ProfileAnalyzeTimeRange range : timeRanges) {
    parser.seekToTime(range.startTime);
    ThreadSnapshot snapshot = parser.nextSnapshot();
    while (snapshot.time < range.endTime) {
      snapshot = parser.nextSnapshot();
    }
    // Add the snapshot to the list if it falls within the given time range
    if (snapshot.time >= range.startTime && snapshot.time <= range.endTime) {
      append(snapshot);
    }
  }

  // Return the list of thread snapshots
  return snapshots;
}

public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file,List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {

  // Initialization
  List<ThreadSnapshot> snapshots = new ArrayList<>();
  FileInputStream fis = null;
  BufferedReader br = null;

  // Error handling
  try {
    fis = new FileInputStream(file);
    br = new BufferedReader(new InputStreamReader(fis, "UTF-8"));

    // Read the first line of the file
    String line = br.readLine();
    while (line != null) {
      // If the line is not a comment, parse it
      if (!line.startsWith("//")) {
        // Get the thread ID and timestamp
        long threadId = Long.parseLong(line.substring(0, line.indexOf(" ")));
        long timestamp = Long.parseLong(line.substring(line.indexOf(" ") + 1));

        // Check if the timestamp falls in the desired time range
        for (ProfileAnalyzeTimeRange range : timeRanges) {
          if (timestamp >= range.getStartTime() && timestamp <= range.getEndTime()) {
            // Add the snapshot to the list
            snapshots.add(new ThreadSnapshot(threadId, timestamp));
            break;
          }
        }
      }
      line = br.readLine();
    }
    return snapshots;
  } catch (FileNotFoundException e) {
    throw new IOException("File not found", e);
  } catch (IOException e) {
    throw new IOException("IOException occurred", e);
  } finally {
    if (fis != null) {
      fis.close();
    }
    if (br != null) {
      br.close();
    }
  }
}
